$name = "Аня";
strlen($name);              // 6 — байты
mb_strlen($name);           // 3 — символы
strtoupper($name);
str_replace("А", "О", $name);
$msg = "Привет, {$name}!";  // интерполяция в двойных кавычках

class User {
    public $name;

    public function __construct($name) {
        $this->name = $name;
    }

    public function hello() {
        return "Привет, {$this->name}";
    }
}

$u = new User("Аня");
echo $u->hello();

